import type { KeyPress, Stop } from '../types.generated.js'

/**
 * Hears the keys pressed on a part with keyboard focus, or anywhere in the
 * window that shows a part: `keydown` on the web, and a native module on iPad
 * and Android, where React Native has no key events.
 */
export interface Keys<N> {
  /**
   * Calls `heard` with each key pressed while `node` has focus, until stopped.
   * Where `heard` answers `true`, the key is taken, and the platform does
   * nothing else with it.
   */
  readonly listen: (node: N, heard: (press: KeyPress) => boolean) => Stop

  /**
   * Calls `heard` with each key pressed in the window that shows `node`,
   * whatever part has focus, before that part hears it, until stopped. Where
   * `heard` answers `true`, the key is taken: the part with focus does not hear
   * it, and the platform does nothing else with it.
   */
  readonly listenAnywhere: (node: N, heard: (press: KeyPress) => boolean) => Stop
}
